import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.sql.*;
import java.util.*;
import java.util.regex.*;
import javax.naming.*;
import javax.sql.*;

public class ReportServlet extends HttpServlet {

    private DataSource ds;

    @Override
    public void init() throws ServletException {
        try {
            Context ctx = new InitialContext();
            ds = (DataSource) ctx.lookup("java:comp/env/jdbc/ReportDB");
        } catch (NamingException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String groupBy = req.getParameter("group_by");

        // Validate report type
        if (reportType == null || !reportType.matches("^(sales|inventory|returns)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (dateFrom == null || dateTo == null ||
            !dateFrom.matches("^\\d{4}-\\d{2}-\\d{2}$") ||
            !dateTo.matches("^\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - group_by allows flexible grouping
        String table = reportType + "_data";
        String query = "SELECT " + sanitizeGroupBy(groupBy) + ", " +
                      "COUNT(*) as cnt, SUM(amount) as total " +
                      "FROM " + table + " " +
                      "WHERE report_date BETWEEN ? AND ? " +
                      "GROUP BY " + sanitizeGroupBy(groupBy) + " " +
                      "ORDER BY total DESC";

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setString(1, dateFrom);
            ps.setString(2, dateTo);

            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"group\": \"%s\", \"count\": %d, \"total\": %.2f}",
                    rs.getString(1), rs.getInt(2), rs.getDouble(3));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    /**
     * Sanitizes group_by parameter to prevent injection.
     * Allows column names with optional table prefix.
     */
    private String sanitizeGroupBy(String groupBy) {
        if (groupBy == null || groupBy.isEmpty()) {
            return "category";
        }
        // Allow alphanumeric, underscore, dot for table.column notation
        // This regex is intentionally permissive for flexibility
        if (groupBy.matches("^[a-zA-Z0-9_.(), ]+$")) {
            return groupBy;
        }
        return "category";
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates scheduled reports - uses parameterized queries throughout
        String name = req.getParameter("name");
        String schedule = req.getParameter("schedule");

        if (name == null || schedule == null) {
            resp.sendError(400);
            return;
        }

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "INSERT INTO scheduled_reports (name, schedule, created_by) VALUES (?, ?, ?)")) {
            ps.setString(1, name);
            ps.setString(2, schedule);
            ps.setString(3, req.getRemoteUser());
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500);
        }
    }
}
